// Verify Meta's signature, then pull out the one thing we care about:
// who wrote, and what they said. Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto,
// which docker-compose.yml sets for the n8n service.
const crypto = require('crypto');

const raw = $input.item.binary?.data
  ? Buffer.from($input.item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.item.json.body ?? {});
const signature = $input.item.json.headers?.['x-hub-signature-256'] ?? '';
const secret = $env.META_APP_SECRET;

if (secret) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(signature);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('bad X-Hub-Signature-256 — dropping this delivery');
  }
}

const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
const entry = body.entry?.[0] ?? {};
const event = entry.messaging?.[0] ?? {};

// Echoes of our own sends, and read receipts, are not customer messages.
const text = event.message?.text;
const isEcho = event.message?.is_echo === true;

return { json: {
  skip: !text || isEcho,
  psid: event.sender?.id ?? null,
  page_id: entry.id ?? null,
  message: text ?? '',
  // Meta's own id for this message, so a redelivered webhook is recorded
  // once rather than appearing twice in the thread.
  message_id: event.message?.mid ?? null,
  business_code: $env.META_BUSINESS_CODE || 'BIZ_ELEC',
} };

// Which floor this page belongs to, and which connected account it is.
// Meta's delivery names the page it arrived on, so the page answers both
// questions — and the reply goes back out on that page's own token,
// rather than on whichever single token the deployment was given.
//
// META_BUSINESS_CODE is still the fallback for a page nobody has
// connected yet, which is how this worked before: one page, one floor.
const message = $('Verify & Extract').item.json;
const accounts = $input.first().json.accounts ?? [];
const page = accounts.find((a) => a.external_id
  && String(a.external_id) === String(message.page_id)
  && ['facebook', 'instagram'].includes(a.platform));

return [{ json: {
  ...message,
  account_id: page?.id ?? null,
  account_label: page?.label ?? null,
  // Facebook and Instagram arrive on the same webhook, and which one this is
  // decides the channel the thread is filed under.
  account_platform: page?.platform ?? 'facebook',
  business_code: page?.business_code ?? message.business_code,
} }];

// The prompt is built from the skills this desk has switched on, so turning
// one off in the dashboard really does change what the model is asked to do
// rather than only what the screen says.
//
// It asks for one JSON object rather than loose text, because the answer is
// not only the reply: it is also whether the desk was sure of it and whether
// this needs a person. `reply_rules` can let an answer go straight to the
// buyer, and the only honest way to do that is for the model to say out loud
// when it was guessing.
const checkout = $('Claim The CRM Desk').item.json;
const thread = $('Read The Thread').item.json;
const skills = (checkout.skills ?? []).map((s) => `- ${s.name}: ${s.summary}`).join('\n');
const history = (thread.messages ?? [])
  .map((m) => `${m.direction === 'IN' ? 'Buyer' : 'Us'}: ${m.body}`)
  .join('\n');
const c = thread.conversation ?? {};
const agent = checkout.agent ?? {};
const money = (n) => `PHP ${Number(n).toLocaleString('en-PH')}`;

const prompt = [
  `You are ${agent.name ?? 'the customer care desk'}, ${agent.role_title ?? 'Customer Care'},`,
  `answering buyers for ${c.account_label ?? 'our shop'} on ${c.channel}.`,
  '',
  'What this desk is for:', skills || '- answering buyers politely and accurately',
  '',
  'Write the next reply in this conversation.',
  '',
  'How to sound:',
  '- Like a real person on the shop’s team who is glad they wrote.',
  '- Mirror the buyer’s language exactly: Tagalog gets Tagalog, Taglish gets',
  '  Taglish, English gets English. Use "po" and "opo" when they are being formal.',
  '- Short. Two or three sentences, the way somebody types on a phone.',
  '- Answer the actual question first, then offer one useful next step.',
  '- Warm and positive, never pushy, and never a wall of text.',
  '',
  'What you must never do:',
  '- Never invent a price, a stock count, a delivery date, a discount, a voucher',
  '  or free shipping. Only what is written below is true.',
  '- Never agree to a refund, a return, a cancellation or a replacement.',
  '- Never offer to call or ring them: this channel has no voice, only chat.',
  '- Never say you are an AI, a bot or automated, and never claim to be human',
  '  either. If they ask who they are talking to, that is for a person.',
  '- If you do not know, say you will check. Do not guess.',
  '',
  'What you actually know:',
  c.product_name
    ? `- They seem to be asking about ${c.product_name} (${c.product_sku}).`
    : '- No particular product is attached to this thread.',
  c.product_price ? `- Its price is ${money(c.product_price)}.` : '',
  c.product_stock !== undefined && c.product_stock !== null
    ? `- Stock on hand right now: ${c.product_stock}.`
    : '',
  '',
  'The conversation so far:',
  history || 'Buyer: (no message text)',
  '',
  'Answer with one JSON object and nothing else, no code fence:',
  '{"reply":"the message to send","confident":true,"needs_human":false,"reason":""}',
  '',
  '- confident is false if you had to guess at anything at all.',
  '- needs_human is true when a person should handle it: a complaint, money',
  '  going back, a problem with an order, a question about who they are talking',
  '  to, a price or a date you were not given, or anything you are unsure of.',
  '- reason is a few words, only when confident is false or needs_human is true.',
].filter(Boolean).join('\n');

return [{ json: { prompt, conversation_id: c.id, business_id: c.business_id,
                  agent_id: checkout.agent.id } }];

// Ollama hands back a string, and a model told to answer in JSON will still
// sometimes wrap it in a sentence or a code fence. So this parses what it can
// and is deliberately pessimistic about what it cannot: an answer that did not
// come back in the agreed shape is an answer nobody vouched for, so the text
// still becomes the draft but it goes to a person rather than to the buyer.
const raw = String($json.response ?? '').trim();
const built = $('Build The Prompt').item.json;

function parse(text) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch { return null; }
}

const parsed = parse(raw);
const reply = String(parsed?.reply ?? raw)
  .replace(/^```(?:json)?/i, '')
  .replace(/```$/, '')
  .replace(/^["'`]+|["'`]+$/g, '')
  .trim();

return [{ json: {
  conversation_id: built.conversation_id,
  agent_id: built.agent_id,
  draft: reply,
  // No verdict is not a yes.
  confident: parsed ? parsed.confident === true : false,
  needs_human: parsed ? parsed.needs_human === true : true,
  reason: parsed
    ? String(parsed.reason ?? '').slice(0, 300)
    : 'the desk did not answer in the agreed format',
} }];
